def check_n(n, limit):
    for a1 in range(2, limit):
        for a2 in range(2, limit):
            a = [0] * (n + 1)
            a[1] = a1
            a[2] = a2
            possible = True
            for i in range(2, n):
                # a[i+1] * a[i-1] = a[i]^2 - 2*a[i] + 2
                # a[i+1] = (a[i]**2 - 2*a[i] + 2) / a[i-1]
                num = a[i]**2 - 2*a[i] + 2
                if num % a[i-1] != 0:
                    possible = False
                    break
                a[i+1] = num // a[i-1]
                if a[i+1] < 2:
                    possible = False
                    break
            if possible:
                return True, a[1:]
    return False, []

for n in range(3, 10):
    found, seq = check_n(n, 100)
    if found:
        print(f"n={n} found: {seq}")
    else:
        print(f"n={n} not found")

