def find_n5(limit):
    for a2 in range(2, limit):
        for a3 in range(2, limit):
            # Check if a1 is an integer >= 2
            num1 = a2**2 - 2*a2 + 2
            if num1 % a3 == 0:
                a1 = num1 // a3
                if a1 >= 2:
                    # Check if a4 is an integer >= 2
                    num2 = a3**2 - 2*a3 + 2
                    if num2 % a2 == 0:
                        a4 = num2 // a2
                        if a4 >= 2:
                            # Check if a5 is an integer >= 2
                            num3 = a4**2 - 2*a4 + 2
                            if num3 % a3 == 0:
                                a5 = num3 // a3
                                if a5 >= 2:
                                    return (a1, a2, a3, a4, a5)
    return None

