def get_divisors(n):
    divs = []
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.append(i)
            if i*i != n:
                divs.append(n // i)
    return divs

def check_n5_efficient(limit):
    for a2 in range(2, limit):
        target = a2**2 - 2*a2 + 2
        divs = get_divisors(target)
        for a1 in divs:
            if a1 < 2:
                continue
            # We want a3 = target / a1. This is already guaranteed.
            # Wait, we need a3 to be a divisor of a2^2 - 2a2 + 2.
            # But the original relation is a1 * a3 = a2^2 - 2a2 + 2.
            # So if a1 is a divisor, then a3 = target // a1.
            a3 = target // a1
            if a3 < 2:
                continue

            # Now check a4
            num2 = a3**2 - 2*a3 + 2
            if num2 % a2 == 0:
                a4 = num2 // a2
                if a4 >= 2:
                    # Now check a5
                    num3 = a4**2 - 2*a4 + 2
                    if num3 % a3 == 0:
                        a5 = num3 // a3
                        if a5 >= 2:
                            return (a1, a2, a3, a4, a5)
    return None

